import{_ as l,o as c,c as i,a2 as s,j as o,t as d,a}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"CI/CD 与发布链门禁（维护者手册）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/ci-gates.md","filePath":"zh/release/ci-gates.md"}'),n={name:"zh/release/ci-gates.md"};function r(t,e,p,g,u,h){return c(),i("div",null,[e[5]||(e[5]=s('<h1 id="ci-cd-与发布链门禁-维护者手册" tabindex="-1">CI/CD 与发布链门禁（维护者手册） <a class="header-anchor" href="#ci-cd-与发布链门禁-维护者手册" aria-label="Permalink to &quot;CI/CD 与发布链门禁（维护者手册）&quot;">​</a></h1><p><code>.github/workflows/build.yml</code> 在每次推送时强制什么、发布链在 tag 移动前检查什么、回归下限如何强制。配套页面： <a href="./process.html">process</a>（这些门禁所挂靠的 SOP）、 <a href="./build-reference.html">build-reference</a>（CI 构建的流水线）、 <a href="./guard-scripts.html">guard-scripts</a>（静态守护）、 <a href="./disaster-recovery.html">disaster-recovery</a>（推送通道）。</p><h2 id="_1-工作流——形态与出处" tabindex="-1">1. 工作流——形态与出处 <a class="header-anchor" href="#_1-工作流——形态与出处" aria-label="Permalink to &quot;1. 工作流——形态与出处&quot;">​</a></h2><p><code>.github/workflows/build.yml</code> 是仓库唯一的 CI 工作流：</p><ul><li><strong>名称</strong> <code>build</code>；<strong>触发器</strong>：push 到 <code>main</code>、PR 到 <code>main</code>、<code>workflow_dispatch</code>；<strong>权限</strong>：<code>contents: read</code>； 一个作业 <code>3.0.0 build (0-warning gate)</code>，运行于 <code>ubuntu-latest</code>、<code>timeout-minutes: 40</code>。</li><li><strong>诚实的出处说明</strong>（声明在文件头）：3.0.0 主线在其最后 一个主线提交时没有 CI 工作流——没有可恢复的东西。本文件 是全新的 WP00 基础设施，使 &quot;CI 绿&quot; 仍是可强制的门禁。 <strong>它构建；它不启动</strong>——每次 QEMU 运行都是仅限沙盒的 验收步骤。</li><li>为什么仅构建的 CI 在这里可以接受：零警告门禁加确定性 构建以机械化方式抓住大多数回归，而启动/E2E 矩阵（§5） 在发布沙盒中经 <code>tools/build_release.sh --deep</code> 运行。流程 用一条硬规则补偿：<strong>tag 必须指向 CI 绿的提交——绝不给 红色提交打 tag</strong>（见 <a href="./process.html">process</a> 第 5 步）。</li></ul><h2 id="_2-六个-ci-步骤逐个说明" tabindex="-1">2. 六个 CI 步骤逐个说明 <a class="header-anchor" href="#_2-六个-ci-步骤逐个说明" aria-label="Permalink to &quot;2. 六个 CI 步骤逐个说明&quot;">​</a></h2><h3 id="第-1-步——带-fetch-depth-0-的-checkout" tabindex="-1">第 1 步——带 <code>fetch-depth: 0</code> 的 Checkout <a class="header-anchor" href="#第-1-步——带-fetch-depth-0-的-checkout" aria-label="Permalink to &quot;第 1 步——带 `fetch-depth: 0` 的 Checkout&quot;">​</a></h3><p><code>actions/checkout@v4</code>，完整历史。<strong>强制项而非装饰</strong>：构建 id 是 <code>git rev-list --count HEAD + 21</code>（<code>Makefile</code> 的 <code>OC_KERNEL_BUILD</code> 推导），且 OTA 更新检查按数值比较构建 id （BUG-0347：仅 remote &gt; local）。浅克隆会把构建 id 烘焙到远 低于已发布的（278/321/414/416），每台已安装机器都会把该 发布当作&quot;降级&quot;静默忽略。一个错误但绿的 CI 构建比没有构建 更糟——因此完整深度是第零步。</p><h3 id="第-2-步——安装工具链" tabindex="-1">第 2 步——安装工具链 <a class="header-anchor" href="#第-2-步——安装工具链" aria-label="Permalink to &quot;第 2 步——安装工具链&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt-get install -y -qq build-essential nasm xorriso mtools \\</span></span>\n<span class="line"><span>  grub-pc-bin grub-efi-amd64-bin grub-common</span></span></code></pre></div><p>正是 <code>tools/build.sh</code> 探测的包集合（外加提供 gcc/ld 的 build-essential）。缺任何一个都会让下一步以编译器/打包器 自己的错误失败。</p><h3 id="第-3-步——选择编译器-优先-gcc-14" tabindex="-1">第 3 步——选择编译器（优先 gcc-14） <a class="header-anchor" href="#第-3-步——选择编译器-优先-gcc-14" aria-label="Permalink to &quot;第 3 步——选择编译器（优先 gcc-14）&quot;">​</a></h3><p>安装 <code>gcc-14</code>（尽力而为，<code>|| true</code>），然后当 <code>command -v gcc-14</code> 成功时输出 <code>cc=gcc-14</code>，否则 <code>cc=gcc</code>。 gcc-14 是发布编译器（Debian gcc 14.2.0——发布构建一直使用的 编译器）；回退使工作流在 runner 镜像变化时不硬失败，代价是 略有不同的代码生成——这本身会被第 5 步的产物断言抓住。</p><h3 id="第-4-步——构建-make-all-——ci-的-lint" tabindex="-1">第 4 步——构建（<code>make all</code>）——CI 的 &quot;lint&quot; <a class="header-anchor" href="#第-4-步——构建-make-all-——ci-的-lint" aria-label="Permalink to &quot;第 4 步——构建（`make all`）——CI 的 &quot;lint&quot;&quot;">​</a></h3>',14)),o("p",null,[o("code",null,"make all CC=$"+d(t.steps.cc.outputs.cc),1),e[0]||(e[0]=a(" 运行完整 WP-13 流水线：userprogs → 内核（两阶段链接）→ 双固件 OCBL ISO → 确定性 src zip → OTA 包。lint 就是构建：每个组件 Makefile （内核、OCIRE、OCBL、OCSE、agent）都带 ",-1)),e[1]||(e[1]=o("code",null,"-Wall -Wextra -Werror",-1)),e[2]||(e[2]=a("，因此任何地方的任何警告都会让 ",-1)),e[3]||(e[3]=o("code",null,"make",-1)),e[4]||(e[4]=a(' 以编译器诊断和非零退出失败。这正是抓住 2.0.0 时代 "本地能编译、CI 上不能"一类问题的门禁（tui_core.c 端口约束 P0）——这也是 SOP 要求本地工具链和 runner 两边都 0 警告的 原因。',-1))]),e[6]||(e[6]=s(`<h3 id="第-5-步——验证产物" tabindex="-1">第 5 步——验证产物 <a class="header-anchor" href="#第-5-步——验证产物" aria-label="Permalink to &quot;第 5 步——验证产物&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>file build/opencube.elf            → grep &#39;ELF 64-bit&#39;</span></span>
<span class="line"><span>file build/opencube.iso            → grep &#39;ISO 9660&#39;</span></span>
<span class="line"><span>test -s build/opencube.elf         (non-empty)</span></span>
<span class="line"><span>test -s build/opencube.iso</span></span>
<span class="line"><span>xorriso -indev ... -report_el_torito plain</span></span>
<span class="line"><span>  → grep &#39;El Torito boot img : 1 BIOS y none&#39;</span></span>
<span class="line"><span>  → grep &#39;El Torito boot img : 2 UEFI y none&#39;</span></span>
<span class="line"><span>test -s dist/OpenCubeOS-src-3.0.0-NAK.zip</span></span>
<span class="line"><span>test -s dist/OpenCubeOS-3.0.0-NAK-update.tar.gz</span></span></code></pre></div><p><strong>三个硬断言</strong>（每个都 grep 真实产物，因此形状错误的产物 无法通过）：</p><ol><li><strong>类型断言</strong>——ELF 必须是 <code>ELF 64-bit</code>，ISO 必须是 <code>ISO 9660</code>，且两者都非空。截断或链接错误的产物在这里 失败。</li><li><strong>双固件 El Torito 断言</strong>——xorriso 报告必须同时显示 <code>El Torito boot img : 1 BIOS y none</code> 和 <code>: 2 UEFI y none</code>。这是同一 ISO 同时携带 BIOS 和 UEFI 启动镜像（OCBL 双固件承诺）的机器检查；仅 BIOS 或仅 UEFI 的 ISO 即便&quot;构建正常&quot;也在这里失败。</li><li><strong>完整性断言</strong>——src zip 和 OTA tar.gz 必须存在且非空 （流水线没有静默跳过一条腿）。</li></ol><h3 id="第-6-步——验证-make-clean-不留产物" tabindex="-1">第 6 步——验证 <code>make clean</code> 不留产物 <a class="header-anchor" href="#第-6-步——验证-make-clean-不留产物" aria-label="Permalink to &quot;第 6 步——验证 \`make clean\` 不留产物&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make clean</span></span>
<span class="line"><span>left=$(find build dist -type f 2&gt;/dev/null | wc -l)</span></span>
<span class="line"><span>test &quot;$left&quot; -eq 0</span></span></code></pre></div><p><code>build dist</code> 下不得残留任何文件。这抓住规则卫生回归：写到 <code>$(BUILD)</code>/<code>$(DIST)</code> 之外的产物，或 clean 规则遗忘的文件， 都会让 <code>left &gt; 0</code> 并使该步失败。</p><h2 id="_3-ci-不运行什么-以及这些门禁住在哪里" tabindex="-1">3. CI 不运行什么（以及这些门禁住在哪里） <a class="header-anchor" href="#_3-ci-不运行什么-以及这些门禁住在哪里" aria-label="Permalink to &quot;3. CI 不运行什么（以及这些门禁住在哪里）&quot;">​</a></h2><p><code>make test</code>（宿主机单元测试桩）、每次 QEMU 启动、31 项检查 回归和 E2E 套件从不在 CI 中运行。它们是沙盒中的发布时 门禁：</p><ul><li><code>tools/build_release.sh &lt;ver&gt; --deep</code>（SOP 第 1–5 步：干净 构建 → reproducible-check → BIOS+UEFI 启动横幅门禁 → 深度 门禁 → 文档/网站数据）——启动门禁每次运行 grep 一个全新 的 mktemp 日志（BUG #63 修复：旧的固定 <code>/tmp/rel_boot.log</code> 让过期日志满足 grep——一个假绿）。</li><li>验证矩阵（<code>make test</code>、<code>run_fix4_regression.py</code> 31/31、 <code>ssh_g11a_e2e.py</code> 5 项检查、<code>run_fix4_https_e2e.py</code> 8 项 检查、<code>wp12_watchdog_logging_e2e.py</code> S1–S14、<code>wp10_*</code> 套件、 大应用冒烟 21/21）——工具见 <a href="./tool-inventory.html">tool-inventory</a>，矩阵见 <a href="./process.html">process</a> 第 4 步。</li></ul><h2 id="_4-发布链——12-项检查逐条说明" tabindex="-1">4. 发布链——12 项检查逐条说明 <a class="header-anchor" href="#_4-发布链——12-项检查逐条说明" aria-label="Permalink to &quot;4. 发布链——12 项检查逐条说明&quot;">​</a></h2><p>在资产上线之后运行（来自 <a href="./process.html">process</a> §8）。每一项 都是带具体验证动作的通过/失败问题：</p><ol><li><strong>两个仓库的远端 HEAD 与本地一致</strong>——对公共仓库和私有 镜像仓 <code>git ls-remote</code> 都显示期望的 SHA（推送确实落地了， 没有哪里是半更新的）。</li><li><strong>tag 存在于公共仓库且指向 CI 绿的提交</strong>——该确切 SHA 的 Actions 运行为绿；绝不给红色提交打 tag。</li><li><strong>每个发布提交的作者身份</strong>——<code>cubestudio-dev &lt;cubestudio@qq.com&gt;</code>；否则 <code>build_release.sh</code> 拒绝启动。</li><li><strong>gh-pages 已更新</strong>——线上站点提供新版本（抓取站点， 检查版本标记）。</li><li><strong><code>update.json</code> 一致性（两份副本）</strong>——version + build + <code>package_sha256</code> 齐全，且两份副本（website/ 顶层和 <code>website/public/</code>）字节一致。</li><li><strong>三方资产哈希</strong>——见下文 §5。</li><li><strong>网站数字从 <code>docs/data/*.json</code> 再生</strong>——命令/接口/行数 计数器与新生成的 JSON 一致，绝不用复制来的过期块（2.0.0 站点就这样发布过一个过期的 130,011 行计数）。</li><li><strong>第 4 步门禁全绿</strong>——把真实输出贴进发布证据，跳过计数 已声明。</li><li><strong>令牌卫生</strong>——任何令牌只有最后 4 个字符出现在日志/ 报告中。</li><li><strong>全仓库数字一致性</strong>——命令首页 / 分类 / L1SVC 操作 / 系统调用计数和 stats.json 行数每次发布都重新计算，绝不 沿用。</li><li><strong>私有镜像仓完整</strong>——三个资产 + 发布说明 + 镜像网站 文件都在镜像仓中（见 <a href="./disaster-recovery.html">disaster-recovery</a> §2）。</li><li><strong>发布提交和被 tag 的提交都 CI 绿</strong>——同一 SHA 检查 两次，因为 tag 可能移动。</li></ol><h2 id="_5-sha256-三方验证" tabindex="-1">5. SHA256 三方验证 <a class="header-anchor" href="#_5-sha256-三方验证" aria-label="Permalink to &quot;5. SHA256 三方验证&quot;">​</a></h2><p>发布说明公布三个资产（ISO、src zip、OTA tar.gz）各自的 SHA256。该检查证明相同字节到达了每个通道：</p><ol><li><strong>本地</strong>：对三个 <code>dist/</code>/<code>build/</code> 产物做 <code>sha256sum</code> （<code>build_release.sh</code> 在门禁化运行结束时打印它们）。</li><li><strong>Release API</strong>：经 API 抓取 GitHub Release 资产元数据， 与平台在上传时计算的摘要比较——抓住截断或错误版本的 上传。</li><li><strong>线上下载</strong>：从用户会使用的公共 URL 下载资产并再次 哈希——抓住 Release 对象与用户实际所得之间的 CDN/缓存/ 重定向漂移。</li></ol><p>每个资产的三方必须相等。同样的纪律延伸到 <code>update.json</code> （OTA 清单携带 <code>package_sha256</code>，因此内核自己的更新器在 安装时重新校验）和站点（<code>website/public/update.json</code> 与 <code>website/update.json</code> 字节一致）。</p><h2 id="_6-回归下限-最低-276-实测-284" tabindex="-1">6. 回归下限：最低 276，实测 284 <a class="header-anchor" href="#_6-回归下限-最低-276-实测-284" aria-label="Permalink to &quot;6. 回归下限：最低 276，实测 284&quot;">​</a></h2><p><code>tools/run_fix4_regression.py</code> 启动构建出的 ISO（512M、 <code>-serial mon:stdio</code>、e1000 用户网络、一个用于帧缓冲断言的 HMP monitor unix socket），等待 <code>ush&gt;</code>，运行 24 条命令并为 <strong>31 项检查</strong>打分；退出码等于失败检查数（发布矩阵引用 31/31）。</p><p>命令计数检查（31 项中的第 6 项）是<strong>接口冻结下限</strong>：</p><ul><li><strong>逻辑</strong>：计数从 <code>help -a</code> 注册表清单（两空格缩进的 <code>name [tag] description</code> 行）动态测量——绝不是过期字面量 （旧门禁 grep <code>Total: 233 commands.</code>，一个在输出中已根本 不存在的字符串）。</li><li><strong>下限</strong>：<code>n &gt;= 276</code>。276 = g3 基线（275）+ p0leak（随门禁 搭车的 WP-fix-critical-security P0 栅栏探针，使每个未来 发布重新证明它）。</li><li><strong>当前实测</strong>：WP-l1apps-merge 树上 284 条命令——下限比 实测面低 8，因此新增命令永远没问题，哪怕移除一个也会让 门禁失败。</li><li><strong>背后的规则</strong>：命令只能新增，不能移除。当实测计数永久 上升时，下限字面量在加入命令的同一提交中上调（绝不提前）。</li></ul><p>烤进同一门禁的防假绿机制（下限为什么不可能被偶然满足）：</p><ul><li>每个模式都限定在一条命令的输出节内（BUG #64 修复：模式 曾匹配整个合并日志，因此命令回显就能满足带名字的模式， 任何地方的任何 PASS 都能满足每个检查——该门禁在结构上 恒真）。</li><li>匹配前剥离回显的命令行。</li><li>帧缓冲检查要求 HMP screendump 有 ≥ 2 种颜色和可测的前景 比例（BUG #66）。</li><li><code>g6_test</code> 异步计数有自己的 300 秒等待窗口。</li></ul><h2 id="_7-build-release-sh——带门禁的正门" tabindex="-1">7. build_release.sh——带门禁的正门 <a class="header-anchor" href="#_7-build-release-sh——带门禁的正门" aria-label="Permalink to &quot;7. build_release.sh——带门禁的正门&quot;">​</a></h2><p><code>tools/build_release.sh &lt;version&gt; [--deep]</code> 自动化 SOP 第 1–5 步，并在以下情况拒绝运行：tag <code>&lt;version&gt;</code> 已存在，或 git 身份不是 <code>cubestudio-dev</code>。序列：干净的 <code>make -j all</code> （0 警告门禁）→ <code>make reproducible-check</code> → BIOS 启动门禁 → UEFI 启动门禁（pflash CODE + 可写 VARS 副本；在当前 OVMF 构建上，朴素的 <code>-bios</code> 形式会静默不运行载荷）→ 可选 <code>--deep</code> 门禁（<code>run_fix4_regression.py</code>、 <code>wp12_watchdog_logging_e2e.py</code>）→ <code>gen_api_docs.py --pages --pages-zh --md</code> + <code>update_website.sh</code> + <code>website/build.sh</code> → 打印三个 SHA256。它不推送任何东西——审查输出，然后手动 运行发布链（有意的不对称；发布链本身是 <a href="./disaster-recovery.html">disaster-recovery</a> 的领地）。</p><p>较老的 <code>tools/github_release_wp08.sh</code>（WP-08 时代）推送 commit+tag 并经 API（带 repo + workflow 权限的 <code>GITHUB_TOKEN</code>）创建带 ISO 资产的 Release——为历史保留； 现代流程从门禁化产物出发手工创建 Release。</p>`,26))])}const _=l(n,[["render",r]]);export{m as __pageData,_ as default};
